let rawSlug = '';
try {
  const hookData = $('Web Server Trigger (GET /storefront)').first().json;
  rawSlug = String(hookData.query?.slug || '').toLowerCase().trim();
} catch (e) {
  rawSlug = String($input.item.json?.query?.slug || '').toLowerCase().trim();
}

const slug = rawSlug.replace(/\/+$/, '').trim();
const allItems = $input.all();
let html = null;
const matches = [];

for (const item of allItems) {
  const row = item.json || {};
  const rowSlug = String(row.slug || '').toLowerCase().trim().replace(/\/+$/, '');
  if (!rowSlug) continue;
  if (row.html_content || row.html) {
    if (rowSlug === slug) matches.push(row.html_content || row.html);
  }
}

// A shop whose address is corrected to its real business name keeps serving its old address too,
// so a link already sent to customers still opens the shop instead of a 404. The store row records
// the address it moved from in previous_slug.
if (matches.length === 0 && slug) {
  for (const item of allItems) {
    const row = item.json || {};
    const movedFrom = String(row.previous_slug || '').toLowerCase().trim().replace(/\/+$/, '');
    const rowSlug = String(row.slug || '').toLowerCase().trim().replace(/\/+$/, '');
    if (!rowSlug || !(row.html_content || row.html)) continue;
    if (movedFrom && movedFrom === slug) { html = row.html_content || row.html; break; }
    // Baserow may hold several retired addresses in a comma-separated list.
    if (movedFrom && movedFrom.split(',').map(v => v.trim()).indexOf(slug) >= 0) { html = row.html_content || row.html; break; }
  }
}

if (matches.length > 0) {
  html = matches[matches.length - 1];
} else if (!html) {
  for (const item of allItems) {
    const row = item.json || {};
    const rowSlug = String(row.slug || '').toLowerCase().trim().replace(/\/+$/, '');
    if (!rowSlug) continue;
    if ((row.html_content || row.html) && (rowSlug.includes(slug) || slug.includes(rowSlug))) {
      html = row.html_content || row.html; break;
    }
  }
}

if (!html && slug && globalThis.xLinkStores) {
  html = globalThis.xLinkStores[slug] || globalThis.xLinkStores[slug + '/'] || null;
  if (!html) {
    const keys = Object.keys(globalThis.xLinkStores);
    const matchedKey = keys.find(k => k.replace(/\/+$/, '') === slug);
    if (matchedKey) html = globalThis.xLinkStores[matchedKey];
  }
}

if (!html && slug) {
  try {
    const staticData = $getWorkflowStaticData('global');
    if (staticData.stores) {
      html = staticData.stores[slug] || staticData.stores[slug + '/'] || null;
      if (!html) {
        const keys = Object.keys(staticData.stores);
        const matchedKey = keys.find(k => k.replace(/\/+$/, '') === slug);
        if (matchedKey) html = staticData.stores[matchedKey];
      }
    }
  } catch (e) {}
}

if (html) return [{ json: { html: html, status: 200 } }];

const fallbackHtml = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Portal Initializing</title>
  <style>
    body { font-family: sans-serif; background: #07090e; color: #fff; display: flex; align-items: center; justify-content: center; height: 100vh; margin: 0; text-align: center; }
    .box { background: #0f1422; padding: 2.5rem; border-radius: 14px; max-width: 440px; border: 1px solid #1e2640; }
    h1 { color: #3b82f6; font-size: 1.4rem; margin-bottom: 0.5rem; }
    p { color: #94a3b8; font-size: 0.95rem; }
  </style>
</head>
<body>
  <div class="box">
    <h1>Portal Initializing</h1>
    <p>We could not find an active storefront matching <code>${escape(slug)}</code>. Please regenerate your site via WhatsApp.</p>
  </div>
</body>
</html>`;

return [{ json: { html: fallbackHtml, status: 404 } }];

const items = $input.all();

const validItems = items.filter(item => {
  const d = item.json || {};
  const lat = parseFloat(d.latitude || d.lat || d.field_lat || d.field_latitude);
  const lng = parseFloat(d.longitude || d.lng || d.field_lng || d.field_longitude);
  return !isNaN(lat) && !isNaN(lng) && lat !== 0 && lng !== 0;
});

const dedupeMap = new Map();
validItems.forEach(item => {
  const d = item.json || {};
  const slug = d.slug || d.field_slug || '';
  if (slug) dedupeMap.set(slug, d);
});

const merchants = Array.from(dedupeMap.values()).map(row => {
  const lat = parseFloat(row.latitude || row.lat || row.field_lat || row.field_latitude);
  const lng = parseFloat(row.longitude || row.lng || row.field_lng || row.field_longitude);
  const name = row.merchant_name || row.name || row.field_merchant_name || 'Official Storefront';
  const category = row.business_category || row.category || row.field_business_category || 'Commercial Trade';
  const headline = row.hero_headline || row.tagline || row.field_hero_headline || 'Direct WhatsApp Merchant';
  const location = row.location || row.field_location || 'Kampala, Uganda';
  const slug = row.slug || row.field_slug || '';
  const phone = String(row.senderPhone || row.phone || row.field_phone || '').replace(/[^0-9]/g, '');
  const tier = row.site_tier || row.field_site_tier || 'MICRO';
  const storeUrl = row.live_store_url || row.field_live_store_url || `https://orchid-frigatebird.pikapod.net/webhook/storefront?slug=${slug}`;

  return { name, category, headline, location, lat, lng, slug, storeUrl, phone, tier };
});

const mapHtml = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no" />
  <title>X-Link | Local Discovery Map</title>
  <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" />
  <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; font-family: 'Plus Jakarta Sans', sans-serif; }
    body, html { width: 100%; height: 100%; overflow: hidden; background: #07090e; color: #f8fafc; }
    #map { width: 100vw; height: 100vh; z-index: 1; position: absolute; inset: 0; }

    /* Optimized Tile Filter for Crystal-Clear Readability */
    /* Normal, readable map tiles. The old dark inversion made roads and labels unreadable. */
    .leaflet-tile-pane { filter: saturate(1.05) brightness(1.02); }

    .map-controls { position: absolute; top: 20px; left: 50%; transform: translateX(-50%); width: 92%; max-width: 650px; z-index: 1000; background: rgba(15, 23, 42, 0.92); backdrop-filter: blur(16px); border: 1px solid rgba(255, 255, 255, 0.12); border-radius: 20px; padding: 14px 18px; box-shadow: 0 16px 40px rgba(0,0,0,0.65); display: flex; flex-direction: column; gap: 12px; }
    .map-brand { display: flex; justify-content: space-between; align-items: center; }
    .map-brand h1 { font-size: 1.1rem; font-weight: 800; color: #fff; display: flex; align-items: center; gap: 8px; letter-spacing: -0.02em; }
    .map-brand span { font-size: 0.72rem; background: #25d366; color: #0f172a; font-weight: 800; padding: 3px 10px; border-radius: 999px; }
    .search-input { width: 100%; background: #07090e; border: 1px solid rgba(255, 255, 255, 0.28); border-radius: 12px; padding: 12px 16px; color: #fff; font-size: 1rem; outline: none; transition: border-color 0.2s; }
    .search-input:focus { border-color: #38bdf8; }

    .category-pills { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 2px; scrollbar-width: none; }
    .category-pills::-webkit-scrollbar { display: none; }
    .pill { background: rgba(255,255,255,0.10); border: 1px solid rgba(255,255,255,0.24); color: #e2e8f0; font-size: 0.88rem; font-weight: 700; padding: 8px 16px; border-radius: 999px; cursor: pointer; white-space: nowrap; transition: all 0.2s; }
    .pill:hover, .pill.active { background: #38bdf8; color: #0f172a; font-weight: 700; border-color: #38bdf8; }

    /* THE CARD HAS TO FIT ON THE SCREEN.
       The popup used to open near the top of the map and slide under the search / category bar, so
       the shop name and its buttons were cut off and the card could not be read or tapped at all.
       It is now a bounded, scrollable card: it never grows past the space between the control bar
       and the bottom of the screen, and its own contents scroll instead of being clipped. */
    .leaflet-popup { max-width: min(94vw, 360px); }
    .leaflet-popup-content-wrapper { background: #0f172a !important; color: #f8fafc !important; border: 1px solid rgba(255, 255, 255, 0.15); border-radius: 18px !important; padding: 6px !important; box-shadow: 0 16px 40px rgba(0,0,0,0.8) !important; }
    .leaflet-popup-content { margin: 0 !important; max-height: 62vh; max-height: 62svh; overflow-y: auto; -webkit-overflow-scrolling: touch; }
    .leaflet-popup-tip { background: #0f172a !important; }
    /* Shop card. Rebuilt for legibility: the category line was tiny, letter-spaced and dark blue
       on dark, the description was 0.85rem mid-grey, and every button was under the 44px touch
       minimum. On a phone in daylight the whole card read as a blur. */
    .pop-card { padding: 14px 14px 12px; min-width: 288px; }
