    .pop-sub { font-size: 1rem; font-weight: 600; color: #f1f5f9; line-height: 1.6; margin-bottom: 16px; }
    /* Section headings were #cbd5e1 grey and disappeared into the dark card. Now white-leaning
       blue at a higher weight, with a hairline underline so each block is clearly separated. */
    .pop-section-label { font-size: 0.82rem; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: #e8f4ff; margin: 16px 0 8px; padding-bottom: 5px; border-bottom: 1px solid rgba(255,255,255,0.18); }
    .pop-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; margin-bottom: 4px; }
    .pop-btn { text-align: center; padding: 13px 12px; min-height: 48px; display: inline-flex; align-items: center; justify-content: center; border-radius: 11px; font-size: 0.98rem; font-weight: 800; line-height: 1.3; text-decoration: none; transition: transform 0.2s; }
    /* One-tap buttons stack full width instead of squeezing two long labels into a half-column. */
    @media (max-width: 420px) { .pop-card { min-width: 250px; } .pop-actions { grid-template-columns: 1fr; } }
    .pop-btn:hover { transform: scale(1.02); }
    .pop-btn-store { background: #38bdf8; color: #0f172a; }
    .pop-btn-wa { background: #25d366; color: #ffffff; }
    .pop-btn-nav { grid-column: span 2; background: #2563eb; color: #ffffff; padding: 12px 14px; border-radius: 10px; font-size: 0.95rem; font-weight: 800; text-decoration: none; display: block; text-align: center; min-height: 48px; line-height: 1.5; }
    .pop-btn-distance { background: #1f9d8b; }
    /* LABEL COLOURS HAVE TO WIN AGAINST LEAFLET'S OWN LINK RULE.
       Leaflet ships its own stylesheet rule for any link inside the map container, colour #0078a8,
       which is more specific than a single class selector like pop-btn-nav. So every button in the
       card kept Leaflet's mid-blue label instead of the colour set here: "Start navigation" was
       mid-blue on a mid-blue button, "Storefront" was pale blue on a pale blue button, and on a
       phone in daylight the card was unreadable. These two-class rules outrank Leaflet's, so each
       label now has the colour it was designed for. The "coming soon" buttons set their colours
       inline, so they were never affected. */
    .leaflet-container .pop-btn, .leaflet-popup .pop-btn { color: #ffffff; }
    .leaflet-container .pop-btn-store, .leaflet-popup .pop-btn-store { color: #0f172a; }
    .leaflet-container .pop-btn-wa, .leaflet-popup .pop-btn-wa { color: #ffffff; }
    .leaflet-container .pop-btn-nav, .leaflet-popup .pop-btn-nav { color: #ffffff; }
    .leaflet-container .pop-btn-distance, .leaflet-popup .pop-btn-distance { color: #ffffff; }
    .leaflet-container .pop-btn:hover, .leaflet-popup .pop-btn:hover { text-decoration: none; }
    /* The two "not live yet" buttons read as clearly secondary: they keep their colour but the
       label carries a small dot so nobody mistakes them for a working booking button. */
    .pop-btn-soon::after { content: ' ·'; opacity: 0.7; }
    .pop-distance { grid-column: span 2; background: rgba(56,189,248,0.16); border: 1px solid rgba(56,189,248,0.55); color: #f0f9ff; border-radius: 10px; padding: 11px 13px; font-size: 0.9rem; font-weight: 700; line-height: 1.5; }
    /* If no shop has a verified map point, say so on the map itself instead of showing a blank
       map that looks broken. */
    .xl-empty { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); z-index: 1000; background: rgba(15,23,42,0.96); border: 1px solid rgba(56,189,248,0.55); color: #f8fafc; padding: 20px 24px; border-radius: 16px; max-width: 88vw; text-align: center; font-size: 1rem; font-weight: 600; line-height: 1.55; box-shadow: 0 16px 40px rgba(0,0,0,0.6); }
    .xl-empty b { color: #38bdf8; }

    .xl-near-btn { position: absolute; left: 50%; transform: translateX(-50%); bottom: 74px; z-index: 1000; background: #1d4ed8; color: #ffffff; border: 2px solid #ffffff; border-radius: 999px; padding: 12px 22px; font-size: 0.9rem; font-weight: 800; box-shadow: 0 12px 30px rgba(0,0,0,0.55); cursor: pointer; }
    .xl-near-btn:hover { background: #1e40af; }

    /* Shop pins. These classes had NO styling at all, so every marker was a zero-size invisible
       div - the map showed tiles but no shops, which is why the map looked "gone". */
    .xl-pin { position: relative; display: flex; flex-direction: column; align-items: center; }
    /* BLINKING BEACONS. A shop on the map is a live thing, so its pin breathes: a soft halo expands
       and fades behind the dot the way a beacon does, and the dot itself swells slightly. Two
       animations on two elements, so the halo never moves the dot out of place. */
    .xl-pin-dot { position: relative; width: 18px; height: 18px; border-radius: 50%; border: 3px solid #ffffff; box-shadow: 0 0 0 2px rgba(15,23,42,0.45), 0 6px 14px rgba(0,0,0,0.55); animation: xl-pin-beat 2.2s ease-in-out infinite; }
    .xl-pin-dot::after { content: ''; position: absolute; left: 50%; top: 50%; width: 18px; height: 18px; margin: -9px 0 0 -9px; border-radius: 50%; background: currentColor; opacity: 0.45; animation: xl-pin-halo 2.2s ease-out infinite; }
    @keyframes xl-pin-beat { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.14); } }
    @keyframes xl-pin-halo { 0% { transform: scale(1); opacity: 0.5; } 70% { transform: scale(3.1); opacity: 0; } 100% { transform: scale(3.1); opacity: 0; } }
    @media (prefers-reduced-motion: reduce) { .xl-pin-dot, .xl-pin-dot::after { animation: none; } }
    .xl-pin-label { margin-top: 4px; max-width: 170px; padding: 4px 10px; border-radius: 999px; background: rgba(15,23,42,0.95); color: #ffffff; font-size: 0.78rem; font-weight: 800; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; border: 1px solid rgba(255,255,255,0.35); }

    /* Distance panel - also had no styling, so its text sat unstyled over the map. */
    .xl-me-panel { position: absolute; left: 50%; transform: translateX(-50%); bottom: 130px; z-index: 1000; background: rgba(15,23,42,0.96); color: #f8fafc; border: 1px solid rgba(56,189,248,0.55); border-radius: 14px; padding: 11px 18px; font-size: 0.92rem; font-weight: 700; max-width: 92%; text-align: center; box-shadow: 0 12px 30px rgba(0,0,0,0.55); }
    .xl-me-panel b { color: #38bdf8; }

    /* The "still in development" message. Sits above the map controls, readable on any tile,
       and disappears on its own so it never blocks the map. */
    .xl-toast { position: fixed; left: 50%; transform: translateX(-50%); bottom: 28px; z-index: 99999; display: none; max-width: 88vw; background: rgba(15,23,42,0.98); color: #f8fafc; border: 1px solid rgba(56,189,248,0.65); border-radius: 14px; padding: 15px 22px; font-size: 0.95rem; font-weight: 600; line-height: 1.5; text-align: center; box-shadow: 0 16px 40px rgba(0,0,0,0.7); }
    .xl-toast b { color: #38bdf8; }

    /* GPS User Marker Glow */
    .user-gps-pin { width: 22px; height: 22px; background: #38bdf8; border: 3px solid #ffffff; border-radius: 50%; box-shadow: 0 0 20px #38bdf8; animation: pulse-gps 2s infinite; }
    @keyframes pulse-gps { 0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(56, 189, 248, 0.7); } 70% { transform: scale(1); box-shadow: 0 0 0 14px rgba(56, 189, 248, 0); } 100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(56, 189, 248, 0); } }
  </style>
</head>
<body>
  <div class="map-controls">
    <div class="map-brand">
      <h1>🌐 X-Link Discovery</h1>
      <span>LIVE</span>
    </div>
    <input type="text" id="searchInput" class="search-input" placeholder="Search a shop, product or place..." oninput="renderMarkers()" />
    <div class="category-pills">
      <button class="pill active" onclick="setCategory('ALL', this)">All</button>
      <button class="pill" onclick="setCategory('TECH', this)">Tech &amp; Electronics</button>
      <button class="pill" onclick="setCategory('FASHION', this)">Fashion &amp; Apparel</button>
      <button class="pill" onclick="setCategory('FOOD', this)">Food &amp; Cafe</button>
    </div>
  </div>

  <div id="map"></div>
  <div class="xl-empty" id="mapEmpty" style="display:none;"><b>No shops pinned here yet.</b><br />A shop shows up on the X-Link map once its location has been confirmed. Ask the merchant to share their location pin on WhatsApp.</div>
  <div class="xl-me-panel" id="myDistancePanel">Location off &mdash; tap <b>Find shops near me</b> to measure distances.</div>
  <button type="button" class="xl-near-btn" id="nearMeBtn" onclick="nearestToMe()">&#128205; Find shops near me</button>

  <script>
    const merchants = ${JSON.stringify(merchants)};

    // Initialize map centered on Kampala by default
    const map = L.map('map', { zoomControl: false }).setView([0.3136, 32.5811], 13);

    L.tileLayer('https://mt1.google.com/vt/lyrs=m&x={x}&y={y}&z={z}', {
      maxZoom: 20,
      noWrap: true,
      attribution: '&copy; Google Maps'
    }).addTo(map);

    L.control.zoom({ position: 'bottomright' }).addTo(map);

    // Fix multi-world tile glitch on render
    setTimeout(() => { map.invalidateSize(); }, 200);

    // Track User GPS Location
    let userMarker = null;
    if (navigator.geolocation) {
      navigator.geolocation.watchPosition(position => {
        const userLat = position.coords.latitude;
        const userLng = position.coords.longitude;

        const userIcon = L.divIcon({
          className: 'custom-user-pin',
          html: '<div class="user-gps-pin"></div>',
          iconSize: [24, 24],
          iconAnchor: [12, 12]
        });

        userPos = { lat: userLat, lng: userLng };
        if (userMarker) {
          userMarker.setLatLng([userLat, userLng]);
        } else {
          userMarker = L.marker([userLat, userLng], { icon: userIcon }).addTo(map).bindPopup("<b>Your Current GPS Location</b>");
        }
      }, err => console.log("GPS Location permission denied or unavailable"), { enableHighAccuracy: true });
    }

    const urlParams = new URLSearchParams(window.location.search);
    const focusLat = urlParams.get('lat') !== null && urlParams.get('lat') !== '' ? parseFloat(urlParams.get('lat')) : null;
    const focusLng = urlParams.get('lng') !== null && urlParams.get('lng') !== '' ? parseFloat(urlParams.get('lng')) : null;
    let urlSearchQuery = (urlParams.get('search') || '').replace(/[\\\\\\\\/\\\\\\\\#?&]+$/, '').trim().toLowerCase();
    if (urlSearchQuery) document.getElementById('searchInput').value = urlSearchQuery;

    let activeCategory = 'ALL';
    let markerStore = [];
    let initialLoad = true;

    // Saturated, deep pin colours with a white outline read clearly on every map shade.
    function getCategoryColor(cat) {
      const c = (cat || '').toLowerCase();
      if (c.match(/tech|electronics|gadget|hardware|computer|phone/)) return '#0284c7';
      if (c.match(/fashion|apparel|wear|clothing|beauty|salon|boutique/)) return '#be185d';
      if (c.match(/food|restaurant|rolex|cafe|bakery|drink/)) return '#c2410c';
      return '#15803d';
    }

    function escapePinText(v) {
      return String(v || '').replace(/[&<>"]/g, function (ch) {
        return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch];
      });
    }

    function createCustomIcon(color, label) {
      const safeLabel = escapePinText(label);
      // The colour is set on the dot AND on the pin wrapper: the pulsing halo is painted from
      // currentColor, so each shop's beacon blinks in that shop's own category colour.
      return L.divIcon({
        className: 'custom-pin',
        html: '<div class="xl-pin" style="color:' + color + ';"><div class="xl-pin-dot" style="background-color:' + color + ';color:' + color + ';"></div>' +
              (safeLabel ? ('<div class="xl-pin-label">' + safeLabel + '</div>') : '') + '</div>',
        iconSize: [30, 34],
        iconAnchor: [15, 18],
        popupAnchor: [0, -18]
      });
    }

    // Straight-line distance between two points, in kilometres.
    function haversineKm(a, b) {
      if (!a || !b) return null;
      const R = 6371;
      const dLat = (b.lat - a.lat) * Math.PI / 180;
      const dLng = (b.lng - a.lng) * Math.PI / 180;
      const s = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
        Math.cos(a.lat * Math.PI / 180) * Math.cos(b.lat * Math.PI / 180) *
        Math.sin(dLng / 2) * Math.sin(dLng / 2);
      return R * 2 * Math.atan2(Math.sqrt(s), Math.sqrt(1 - s));
    }

    function kmText(km) {
      if (km === null || !isFinite(km)) return '';
      return km < 1 ? (Math.round(km * 1000) + ' m') : (km.toFixed(km < 10 ? 1 : 0) + ' km');
    }

    // Road distance, measured inside this map. If the routing service cannot be reached the
    // straight-line figure is shown and labelled as a straight line - never dressed up as a
    // road distance.
    function roadKm(from, to, done) {
      const straight = haversineKm(from, to);
      let settled = false;
      function finish(km, road) {
        if (settled) return;
        settled = true;
        done(km, road);
      }
      try {
        const url = 'https://router.project-osrm.org/route/v1/driving/' +
          from.lng + ',' + from.lat + ';' + to.lng + ',' + to.lat + '?overview=false';
        fetch(url).then(function (r) { return r.json(); }).then(function (data) {
          if (data && Array.isArray(data.routes) && data.routes[0] && data.routes[0].distance) {
            finish(data.routes[0].distance / 1000, true);
          } else {
            finish(straight, false);
          }
        }).catch(function () { finish(straight, false); });
      } catch (e) {
        finish(straight, false);
      }
      setTimeout(function () { finish(straight, false); }, 6000);
    }

    // The last known position of the buyer, once the browser has allowed GPS.
    let userPos = null;

    // ── Features that are not switched on yet ────────────────────────────────────
    // SafeBoda rides and Mobile Money payments are not wired up on this platform yet. The map
    // shows the buttons so the shop reads as complete and the intent is visible, and tapping one
    // says plainly that it is still in development. It never opens a dead link, never pretends to
    // book a ride, and never takes money.
    function comingSoon(ev, el) {
      if (ev) ev.preventDefault();
      // The feature name comes from the button's data attribute, so nothing has to be quoted
      // inside the generated markup.
      var what = (el && el.getAttribute) ? (el.getAttribute('data-soon') || 'This feature') : 'This feature';
      var toast = document.getElementById('xlToast');
      if (!toast) {
        toast = document.createElement('div');
        toast.id = 'xlToast';
        toast.className = 'xl-toast';
        document.body.appendChild(toast);
      }
      toast.innerHTML = '<b>' + String(what || 'This feature') + '</b> is still in development. It will be available here soon.';
      toast.style.display = 'block';
      if (window.__xlToastTimer) clearTimeout(window.__xlToastTimer);
      window.__xlToastTimer = setTimeout(function () { toast.style.display = 'none'; }, 6000);
    }

    function startNav(ev, lat, lng) {
      if (ev) ev.preventDefault();
      // Turn-by-turn opens from the map the buyer is already on, so the pin they were looking
      // at is the destination rather than a search for the shop's name.
      const dest = lat + ',' + lng;
      const url = 'https://www.google.com/maps/dir/?api=1&destination=' + encodeURIComponent(dest) + '&travelmode=driving';
      window.open(url, '_blank');
    }

    function distanceLabel(el, km, road, fromGps) {
      if (!el) return;
      if (km === null || !isFinite(km)) {
        el.innerHTML = 'Turn on location to see how far this is from you.';
        return;
      }
      el.innerHTML = (fromGps ? 'About <b>' : '<b>') + kmText(km) + '</b> from you' +
        (road ? ' by road' : (fromGps ? ' in a straight line' : ' in a straight line')) +
        (fromGps ? '' : ' (approximate - city centre)');
    }

    function showDistance(ev, lat, lng, btn) {
      if (ev) ev.preventDefault();
      const card = btn ? btn.closest('.pop-card') : null;
      const box = card ? card.querySelector('#popDistance') : document.getElementById('popDistance');
      const dest = { lat: Number(lat), lng: Number(lng) };
      const origin = userPos;
      if (!origin) {
        // No GPS yet: ask for it rather than guessing where the buyer is.
        if (box) box.innerHTML = 'Waiting for your location...';
        if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition(function (pos) {
            userPos = { lat: pos.coords.latitude, lng: pos.coords.longitude };
            roadKm(userPos, dest, function (km, road) { distanceLabel(box, km, road, true); });
          }, function () {
            if (box) box.innerHTML = 'Location is off. Turn it on to see the distance from where you are.';
          }, { enableHighAccuracy: true, timeout: 12000 });
        } else if (box) {
          box.innerHTML = 'This device cannot share its location.';
        }
        return;
      }
      if (box) box.innerHTML = 'Measuring the distance...';
      roadKm(origin, dest, function (km, road) { distanceLabel(box, km, road, true); });
    }

    function renderMarkers() {
      markerStore.forEach(m => map.removeLayer(m.layer));
      markerStore = [];

      const query = document.getElementById('searchInput').value.toLowerCase().trim();

      merchants.forEach(m => {
        const catLower = (m.category || '').toLowerCase();
        const catMatch = activeCategory === 'ALL' || 
          (activeCategory === 'TECH' && catLower.match(/tech|electronics|gadget|hardware|computer|phone/)) ||
          (activeCategory === 'FASHION' && catLower.match(/fashion|apparel|wear|clothing|beauty|salon|boutique/)) ||
          (activeCategory === 'FOOD' && catLower.match(/food|restaurant|rolex|cafe|bakery/));

        const textMatch = !query || 
          m.name.toLowerCase().includes(query) || 
          m.headline.toLowerCase().includes(query) || 
          m.location.toLowerCase().includes(query) ||
          m.category.toLowerCase().includes(query);

        if (catMatch && textMatch) {
          const color = getCategoryColor(m.category);
          const safeName = escapePinText(m.name);
          const safeCat = escapePinText(m.category);
          const safeLoc = escapePinText(m.location);
          const safeSub = escapePinText(m.headline);
          const safeUrl = escapePinText(m.storeUrl);
          // THE MENU IS GROUPED SO IT CAN BE READ.
          // It was one undifferentiated stack of coloured bars, and the card could not be seen on a
          // phone at all (cut off under the search bar). Now it reads in three labelled blocks:
          // the shop's own links, getting to it, and the two features that are not live yet.
          const popupContent =
            '<div class="pop-card" data-lat="' + m.lat + '" data-lng="' + m.lng + '">' +
              '<div class="pop-tag">' + safeCat + ' &bull; ' + safeLoc + '</div>' +
              '<div class="pop-title">' + safeName + '</div>' +
              (safeSub ? '<div class="pop-sub">' + safeSub + '</div>' : '') +
              '<div class="pop-section-label">Visit the shop</div>' +
              '<div class="pop-actions">' +
                '<a href="' + safeUrl + '" target="_blank" class="pop-btn pop-btn-store">Storefront &nearr;</a>' +
                (m.phone ? ('<a href="https://wa.me/' + escapePinText(m.phone) + '" target="_blank" class="pop-btn pop-btn-wa">WhatsApp &nearr;</a>') : '') +
              '</div>' +
              '<div class="pop-section-label">Getting there</div>' +
              '<div class="pop-actions">' +
                '<a href="#" class="pop-btn pop-btn-nav" onclick="startNav(event, ' + m.lat + ', ' + m.lng + ')">&#129517; Start navigation</a>' +
                '<a href="#" class="pop-btn pop-btn-nav pop-btn-distance" onclick="showDistance(event, ' + m.lat + ', ' + m.lng + ', this)">&#128207; Show distance</a>' +
                '<div class="pop-distance" id="popDistance">Tap "Show distance" to see how far this is from you.</div>' +
              '</div>' +
              // ── Ride-hailing and mobile money ────────────────────────────────────
              // SafeBoda is Uganda's boda-boda ride-hailing app, so a buyer looking at a shop wants
              // to book the ride from right here. This platform has no SafeBoda integration, so
              // the button is shown, looks like the others, and says plainly that it is still in
              // development - it never opens a dead link and never pretends to book anything.
              // The label travels in a data attribute: a quote inside this single-quoted JS string
              // would terminate it and break the whole page script.
              '<div class="pop-section-label">Coming soon</div>' +
              '<div class="pop-actions">' +
                '<a href="#" class="pop-btn pop-btn-soon" style="background:#f59e0b;color:#0f172a;" data-soon="SafeBoda ride" onclick="comingSoon(event, this)">&#128757; Ride with SafeBoda</a>' +
                '<a href="#" class="pop-btn pop-btn-soon" style="background:#7c3aed;color:#ffffff;" data-soon="Mobile Money payment" onclick="comingSoon(event, this)">&#128241; Pay with Mobile Money</a>' +
              '</div>' +
            '</div>';

          const marker = L.marker([m.lat, m.lng], { icon: createCustomIcon(color, m.name) }).addTo(map).bindPopup(popupContent);
          markerStore.push({ data: m, layer: marker });
        }
      });

      // Nothing to show: explain it, never leave a silent empty map. A shop appears here once the
      // merchant's location has been confirmed, so a missing pin is a setup gap, not a broken map.
      var emptyBox = document.getElementById('mapEmpty');
      if (emptyBox) emptyBox.style.display = markerStore.length ? 'none' : 'block';

      if (initialLoad && markerStore.length > 0 && (urlSearchQuery || focusLat !== null)) {
        // Open the card where it can actually be seen: the map pans so the pin sits low on the
        // screen, leaving the upper half for the popup instead of pushing it under the control bar.
        const panForPopup = (layer) => {
          try {
            map.panInside(layer.getLatLng(), { paddingTopLeft: [10, 110], paddingBottomRight: [10, 40] });
          } catch (e) {}
        };
        let targetMarker = null;
        if (focusLat !== null && focusLng !== null) {
          // Opened from a shop's page with its exact point: centre on that shop, not on a name
          // that other businesses may share.
          let best = null;
          markerStore.forEach(function (entry) {
            const d = haversineKm({ lat: focusLat, lng: focusLng }, { lat: entry.data.lat, lng: entry.data.lng });
            if (d !== null && (best === null || d < best)) { best = d; targetMarker = entry.layer; }
          });
        }
        if (!targetMarker) targetMarker = markerStore[0].layer;
        map.flyTo(targetMarker.getLatLng(), 16, { animate: true, duration: 1.5 });
        setTimeout(() => { targetMarker.openPopup(); panForPopup(targetMarker); }, 1500);
        initialLoad = false;
      }
    }

    function setCategory(cat, el) {
      document.querySelectorAll('.pill').forEach(p => p.classList.remove('active'));
      el.classList.add('active');
      activeCategory = cat;
      renderMarkers();
    }

    function nearestToMe() {
      const btn = document.getElementById('nearMeBtn');
      const panel = document.getElementById('myDistancePanel');
      function show() {
        panel.style.display = 'block';
        const rows = [];
        const origin = userPos;
        let pending = markerStore.length;
        if (!pending) { panel.innerHTML = 'No shops are shown right now.'; return; }
        markerStore.forEach(function (entry) {
          const m = entry.data;
          roadKm(origin, { lat: m.lat, lng: m.lng }, function (km, road) {
            rows.push({ m: m, km: km, road: road });
            pending--;
            if (pending > 0) return;
            rows.sort(function (x, y) {
              const a = x.km === null ? Infinity : x.km;
              const b = y.km === null ? Infinity : y.km;
              return a - b;
            });
            let html = '<div style="font-weight:800;margin-bottom:6px;">Closest to you</div>';
            rows.slice(0, 4).forEach(function (r) {
              html += '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin:6px 0;">' +
                '<span style="font-weight:700;">' + escapePinText(r.m.name) + '</span>' +
                '<span>' + kmText(r.km) + (r.road ? '' : '*') + '</span>' +
                '<a href="#" onclick="startNav(event, ' + r.m.lat + ', ' + r.m.lng + ')" style="background:#1d4ed8;color:#fff;border-radius:8px;padding:5px 10px;font-size:0.75rem;font-weight:800;">Go</a>' +
                '</div>';
            });
            html += '<div style="font-size:0.7rem;opacity:0.75;margin-top:4px;">* straight line</div>';
            panel.innerHTML = html;
          });
        });
      }
      if (userPos) { show(); return; }
      panel.style.display = 'block';
      panel.innerHTML = 'Getting your location...';
      if (!navigator.geolocation) { panel.innerHTML = 'This device cannot share its location.'; return; }
      navigator.geolocation.getCurrentPosition(function (pos) {
        userPos = { lat: pos.coords.latitude, lng: pos.coords.longitude };
        show();
      }, function () {
        panel.innerHTML = 'Location is off. Turn it on to measure the distance to the shops.';
      }, { enableHighAccuracy: true, timeout: 12000 });
    }

    renderMarkers();
  </script>
</body>
</html>`;

